      "intro.title": "O que o Kindle EPUB Fix faz",
      "intro.lead": "O Send to Kindle rejeita arquivos EPUB sem nunca dizer por quê. A causa quase sempre é estrutural: um mimetype gravado no lugar errado, um manifesto OPF quebrado, links internos apontando para arquivos que não existem mais ou um sumário que o Kindle não consegue ler. O Kindle EPUB Fix abre o livro, lista todos os problemas encontrados e reconstrói o pacote para a Amazon aceitar.",
