      "option.rebuildChapters.title": "Reconstruir capítulos en el índice",
      "option.rebuildChapters.description": "Detecta capítulos que existen en el libro pero faltan en el índice y los añade, para que Kindle reconozca cada uno. Reemplaza el índice actual. También divide los capítulos muy largos en partes más pequeñas usando los espaciados internos, para que Kindle pueda navegar por cada parte.",
