      "document.title": "Kindle EPUB Fix — Send to Kindle-এর জন্য EPUB ফাইল ঠিক করুন",
      "language.label": "ভাষা",
      "hero.eyebrow": "১০০% লোকাল · কোনো আপলোড নেই",
      "hero.copy": "Send to Kindle-এর সঙ্গে সামঞ্জস্য বাড়াতে EPUB ফাইল বিশ্লেষণ, মেরামত ও পুনর্গঠন করে।",
      "intro.kicker": "কিন্ডলের জন্য বিনামূল্যে EPUB মেরামত",
      "intro.title": "Kindle EPUB Fix কী করে",
      "intro.lead": "Send to Kindle কারণ না জানিয়েই EPUB ফাইল প্রত্যাখ্যান করে। কারণটা প্রায় সবসময়ই কাঠামোগত: ভুল জায়গায় রাখা mimetype, ভেঙে যাওয়া OPF ম্যানিফেস্ট, এমন ফাইলের দিকে নির্দেশ করা অভ্যন্তরীণ লিঙ্ক যেগুলো আর নেই, কিংবা এমন সূচিপত্র যা কিন্ডল পড়তে পারে না। Kindle EPUB Fix বইটি খোলে, খুঁজে পাওয়া প্রতিটি সমস্যা তালিকাভুক্ত করে এবং প্যাকেজটি এমনভাবে নতুন করে গড়ে তোলে যাতে অ্যামাজন তা গ্রহণ করে।",
      "intro.privacy": "আপনার বই কখনও আপনার কম্পিউটার ছেড়ে যায় না। কোনো সার্ভার নেই, আপলোড নেই, অ্যাকাউন্টও লাগে না: পুরো মেরামত এই ব্রাউজার ট্যাবের ভেতরেই চলে, আর ঠিক করা EPUB সরাসরি আপনার ডিভাইসে সংরক্ষিত হয়। এটি বিনামূল্যে এবং যেকোনো EPUB-এ কাজ করে, এমনকি অন্য অ্যাপ থেকে রপ্তানি করা বইয়েও।",
      "intro.diagnose.title": "কিছু বদলানোর আগেই পূর্ণ নির্ণয়",
      "intro.diagnose.description": "প্রতিটি সমস্যা তার তীব্রতা ও যে ফাইল থেকে এসেছে তার সঙ্গে দেখানো হয়, সঙ্গে থাকে ০ থেকে ১০০ পর্যন্ত সামঞ্জস্য স্কোর। কী ভুল ছিল আর কী ঠিক হয়েছে, তা স্পষ্ট বোঝা যায়।",
      "intro.package.title": "প্যাকেজ ও কাঠামো মেরামত",
      "intro.package.description": "mimetype সবার আগে ও সংকোচন ছাড়া রেখে ZIP নতুন করে তৈরি করে, OPF-এর ম্যানিফেস্ট ও spine ঠিক করে, অনুপস্থিত ID ও মিডিয়া টাইপ ফিরিয়ে আনে, ফাইলের পথ স্বাভাবিক করে এবং macOS, উইন্ডোজ ও সম্পাদকের ফেলে যাওয়া অপ্রয়োজনীয় ফাইল সরায়।",
      "intro.toc.title": "নতুন করে গড়া সূচিপত্র",
      "intro.toc.description": "বইয়ে আছে অথচ সূচিপত্রে নেই এমন অধ্যায় খুঁজে বের করে, NAV ও NCX নেভিগেশন নতুন করে তৈরি করে, আর খুব লম্বা অধ্যায়গুলোকে বইয়েরই দৃশ্য-বিরতি অনুসরণ করে চলাচলযোগ্য অংশে ভাগ করে।",
      "intro.margins.title": "সরাসরি প্রাকদর্শনসহ সমন্বয়যোগ্য মার্জিন",
      "intro.margins.description": "ই-ইঙ্ক পর্দায় বেশি লেখা আঁটাতে পাশের মার্জিন ছোট করুন বা প্রায় মুছে দিন। অন্তর্নির্মিত প্রাকদর্শন সত্যিকারের অধ্যায় দেখায়, তাই কিছু মেরামতের আগেই মূলের সঙ্গে তুলনা করতে পারেন।",
      "intro.batch.title": "একাধিক বইয়ের জন্য ব্যাচ মোড",
      "intro.batch.description": "যত খুশি EPUB ফাইল সারিতে রাখুন। প্রতিটি ফাইল তার নিজস্ব মেরামত বিকল্প ধরে রাখে, আর কাজ শেষে গোটা সারি একটিমাত্র ZIP হিসেবে নামানো যায়।",
      "intro.report.title": "নামানোর উপযোগী বিস্তারিত প্রতিবেদন",
      "intro.report.description": "প্রতিটি বইয়ে কী বদলাল তার নথি হিসেবে, সম্পূর্ণ নির্ণয়টি আপনার বেছে নেওয়া ভাষায় JSON ফাইলে সংরক্ষণ করুন। প্রচ্ছদ, DRM ও দূরবর্তী রিসোর্স নিয়েও জানানো হয়।",
      "privacy.title": "ফাইলটি শুধু আপনার ব্রাউজারেই প্রক্রিয়া করা হয়।",
      "privacy.label": "লোকাল প্রসেসিং",
