      "option.rebuildChapters.title": "সূচিপত্রে অধ্যায় পুনর্নির্মাণ করুন",
      "option.rebuildChapters.description": "বইয়ে থাকা কিন্তু সূচিপত্রে অনুপস্থিত অধ্যায়গুলি শনাক্ত করে যুক্ত করে, যাতে Kindle প্রতিটি অধ্যায় চিনতে পারে। এটি বর্তমান সূচিপত্র প্রতিস্থাপন করে। এটি অভ্যন্তরীণ ফাঁক ব্যবহার করে খুব দীর্ঘ অধ্যায়গুলিকে ছোট অংশে ভাগ করে, যাতে Kindle প্রতিটি অংশে নেভিগেট করতে পারে।",
