      "hero.eyebrow": "100% локально · без загрузок",
      "hero.copy": "Анализирует, восстанавливает и пересобирает файлы EPUB для улучшения совместимости с Send to Kindle.",
      "intro.kicker": "Бесплатное восстановление EPUB для Kindle",
      "intro.title": "Что делает Kindle EPUB Fix",
      "intro.lead": "Send to Kindle отклоняет файлы EPUB, никогда не объясняя причину. Причина почти всегда структурная: mimetype, сохранённый не в том месте, повреждённый манифест OPF, внутренние ссылки на файлы, которых больше нет, или оглавление, которое Kindle не может прочитать. Kindle EPUB Fix открывает книгу, перечисляет все найденные проблемы и пересобирает пакет так, чтобы Amazon его принял.",
      "intro.privacy": "Ваша книга никогда не покидает компьютер. Нет ни сервера, ни загрузки, ни учётной записи: всё восстановление выполняется прямо в этой вкладке браузера, а исправленный EPUB сохраняется сразу на ваше устройство. Это бесплатно и работает с любым EPUB, включая книги, экспортированные из другого приложения.",
      "intro.diagnose.title": "Полная диагностика до любых изменений",
      "intro.diagnose.description": "Каждая проблема указана с её серьёзностью и файлом, из которого она пришла, плюс оценка совместимости от 0 до 100. Вы точно видите, что было не так и что было исправлено.",
      "intro.package.title": "Восстановление пакета и структуры",
      "intro.package.description": "Пересобирает ZIP так, чтобы mimetype шёл первым и без сжатия, исправляет манифест и spine в OPF, восстанавливает отсутствующие идентификаторы и типы MIME, нормализует пути к файлам и удаляет мусор, оставленный macOS, Windows и редакторами.",
      "intro.toc.title": "Пересобранное оглавление",
      "intro.toc.description": "Находит главы, которые есть в книге, но отсутствуют в оглавлении, заново создаёт навигацию NAV и NCX и делит очень длинные главы на удобные для навигации части по собственным разрывам сцен книги.",
      "intro.margins.title": "Настраиваемые поля с предпросмотром",
      "intro.margins.description": "Уменьшите боковые поля или уберите их почти полностью, чтобы на экране с электронными чернилами помещалось больше текста. Встроенный предпросмотр показывает настоящие главы, так что можно сравнить с оригиналом до любого исправления.",
      "intro.batch.title": "Пакетный режим для нескольких книг",
      "intro.batch.description": "Ставьте в очередь сколько угодно файлов EPUB. У каждого файла свои настройки восстановления, а всю очередь по завершении можно скачать одним архивом ZIP.",
      "intro.report.title": "Подробный отчёт для скачивания",
      "intro.report.description": "Сохраните полную диагностику в файл JSON на выбранном вами языке — как запись того, что изменилось в каждой книге. Обложки, DRM и удалённые ресурсы тоже попадают в отчёт.",
      "privacy.title": "Файл обрабатывается только в вашем браузере.",
      "privacy.label": "Локальная обработка",
