      "option.repairNavigation.title": "Восстановить оглавления NAV и NCX",
      "option.repairNavigation.description": "Создаёт совместимую навигацию, если она отсутствует или пуста.",
      "option.rebuildChapters.title": "Перестроить главы в оглавлении",
      "option.rebuildChapters.description": "Находит главы, которые есть в книге, но отсутствуют в оглавлении, и добавляет их, чтобы Kindle распознавал каждую. Заменяет текущее оглавление. Также разбивает очень длинные главы на меньшие части, используя внутренние отступы, чтобы Kindle мог переходить к каждой части.",
      "option.repairText.title": "Восстановить XHTML, XML и CSS",
