      "settings.scope": "Einstellungen für: {{file}}",
      "settings.applyToAll": "Auf alle Dateien anwenden",
      "settings.hint": "Die empfohlenen Standardeinstellungen sind bereits aktiv",
      "settings.structure": "EPUB-Struktur",
      "settings.content": "Paket und Inhalt",
      "option.fixZip.title": "ZIP-Paket neu erstellen",
      "option.fixZip.description": "Stellt mimetype an den Anfang und speichert es ohne Komprimierung.",
      "option.normalizePaths.title": "Namen und Pfade normalisieren",
      "option.normalizePaths.description": "Behebt Leerzeichen, problematische Akzente, Prozentkodierung, Schrägstriche und Groß-/Kleinschreibung.",
      "option.removeJunk.title": "Überflüssige Dateien entfernen",
      "option.removeJunk.description": "Löscht von macOS, Windows und Editoren hinterlassene Dateien.",
      "option.repairPackage.title": "OPF, Manifest und Spine reparieren",
      "option.repairPackage.description": "Behebt IDs, fehlende Elemente, Medientypen und Lesereihenfolge.",
      "option.repairNavigation.title": "NAV- und NCX-Inhaltsverzeichnisse reparieren",
      "option.repairNavigation.description": "Erstellt eine kompatible Navigation, wenn sie fehlt oder leer ist.",
      "option.rebuildChapters.title": "Kapitel im Inhaltsverzeichnis neu aufbauen",
      "option.rebuildChapters.description": "Erkennt Kapitel, die im Buch vorhanden sind, aber im Inhaltsverzeichnis fehlen, und fügt sie hinzu, damit Kindle jedes erkennt. Ersetzt das aktuelle Inhaltsverzeichnis. Außerdem teilt es sehr lange Kapitel anhand der internen Abstände in kleinere Teile auf, damit Kindle jeden Teil ansteuern kann.",
      "option.repairText.title": "XHTML, XML und CSS reparieren",
      "option.repairText.description": "Entfernt ungültige Zeichen, BOMs und defekte Verweise.",
      "option.repairCover.title": "Cover erkennen und einrichten",
      "option.repairCover.description": "Behebt die cover-image-Eigenschaft und veraltete Cover-Metadaten.",
      "advanced.title": "Erweiterte Optionen",
      "option.addUnlisted.title": "Nicht gelistete Dateien zum Manifest hinzufügen",
      "option.addUnlisted.description": "Bindet im Paket gefundene XHTML, CSS, Bilder und Schriften ein.",
      "option.removeMissing.title": "Verweise auf fehlende Dateien entfernen",
      "option.removeMissing.description": "Verhindert Fehler durch Manifest-Elemente, die nicht existieren.",
      "option.stripScripts.title": "JavaScript aus dem Buch entfernen",
      "option.stripScripts.description": "Kann bei interaktiven EPUBs helfen, die von Kindle abgelehnt werden.",
      "option.reduceMargins.title": "Seitenränder verkleinern",
      "option.reduceMargins.description": "Verringert den Leerraum an den Textseiten, um den Bildschirm besser zu nutzen.",
      "option.miniMargins.title": "Mini-Ränder (nahezu randlos)",
      "option.miniMargins.description": "Verkleinert sie noch weiter, sodass der Text fast bündig an den Bildschirmrändern sitzt. Das Aktivieren deaktiviert die Option oben.",
      "action.kicker": "Ausführung",
