      "option.rebuildChapters.title": "విషయ సూచికలో అధ్యాయాలను పునర్నిర్మించండి",
      "option.rebuildChapters.description": "పుస్తకంలో ఉన్నా విషయ సూచికలో లేని అధ్యాయాలను గుర్తించి జోడిస్తుంది, తద్వారా Kindle ప్రతి ఒక్కదాన్ని గుర్తిస్తుంది. ఇది ప్రస్తుత విషయ సూచికను భర్తీ చేస్తుంది. అంతర్గత ఖాళీలను ఉపయోగించి చాలా పొడవైన అధ్యాయాలను చిన్న భాగాలుగా కూడా విభజిస్తుంది, తద్వారా Kindle ప్రతి భాగానికి నావిగేట్ చేయగలదు.",
