      "settings.hint": "பரிந்துரைக்கப்பட்ட இயல்புநிலைகள் ஏற்கனவே இயக்கத்தில் உள்ளன",
      "settings.structure": "EPUB அமைப்பு",
      "settings.content": "தொகுப்பு மற்றும் உள்ளடக்கம்",
      "option.fixZip.title": "ZIP தொகுப்பை மீண்டும் உருவாக்கு",
      "option.fixZip.description": "mimetype ஐ முதலில் வைத்து, சுருக்கம் இல்லாமல் சேமிக்கிறது.",
      "option.normalizePaths.title": "பெயர்கள் மற்றும் பாதைகளை இயல்பாக்கு",
      "option.normalizePaths.description": "இடைவெளிகள், சிக்கலான உச்சரிப்புக் குறிகள், சதவீத குறியாக்கம், சாய்வுக் கோடுகள், எழுத்து வடிவம் ஆகியவற்றை சரிசெய்கிறது.",
      "option.removeJunk.title": "தேவையற்ற கோப்புகளை அகற்று",
      "option.removeJunk.description": "macOS, Windows, திருத்திகள் விட்டுச்செல்லும் கோப்புகளை நீக்குகிறது.",
      "option.repairPackage.title": "OPF, manifest, spine ஐ சரிசெய்",
      "option.repairPackage.description": "ID கள், விடுபட்ட உருப்படிகள், மீடியா வகைகள், படிக்கும் வரிசையை சரிசெய்கிறது.",
      "option.repairNavigation.title": "NAV மற்றும் NCX உள்ளடக்க அட்டவணைகளை சரிசெய்",
      "option.repairNavigation.description": "வழிசெலுத்தல் இல்லாதபோது அல்லது காலியாக இருக்கும்போது இணக்கமான வழிசெலுத்தலை உருவாக்குகிறது.",
      "option.rebuildChapters.title": "பொருளடக்கத்தில் அத்தியாயங்களை மீண்டும் உருவாக்கு",
      "option.rebuildChapters.description": "புத்தகத்தில் இருக்கும் ஆனால் பொருளடக்கத்தில் இல்லாத அத்தியாயங்களைக் கண்டறிந்து சேர்க்கிறது, இதனால் Kindle ஒவ்வொன்றையும் அடையாளம் காணும். இது தற்போதைய பொருளடக்கத்தை மாற்றுகிறது. உள் இடைவெளிகளைப் பயன்படுத்தி மிக நீளமான அத்தியாயங்களைச் சிறிய பகுதிகளாகவும் பிரிக்கிறது, இதனால் Kindle ஒவ்வொரு பகுதிக்கும் செல்ல முடியும்.",
      "option.repairText.title": "XHTML, XML, CSS ஐ சரிசெய்",
      "option.repairText.description": "தவறான எழுத்துகள், BOM கள், உடைந்த குறிப்புகளை அகற்றுகிறது.",
      "option.repairCover.title": "அட்டையைக் கண்டறிந்து அமை",
      "option.repairCover.description": "cover-image பண்பு மற்றும் பழைய அட்டை மெட்டாடேட்டாவை சரிசெய்கிறது.",
      "advanced.title": "மேம்பட்ட விருப்பங்கள்",
      "option.addUnlisted.title": "பட்டியலிடப்படாத கோப்புகளை manifest இல் சேர்",
      "option.addUnlisted.description": "தொகுப்பில் காணப்படும் XHTML, CSS, படங்கள், எழுத்துருக்களை உள்ளடக்குகிறது.",
      "option.removeMissing.title": "விடுபட்ட கோப்புகளுக்கான குறிப்புகளை அகற்று",
      "option.removeMissing.description": "இல்லாத manifest உருப்படிகளால் ஏற்படும் தோல்விகளைத் தடுக்கிறது.",
      "option.stripScripts.title": "புத்தகத்திலிருந்து JavaScript ஐ அகற்று",
      "option.stripScripts.description": "Kindle நிராகரிக்கும் ஊடாடும் EPUB களுக்கு உதவலாம்.",
      "option.reduceMargins.title": "பக்க ஓரங்களைக் குறை",
      "option.reduceMargins.description": "திரையை சிறப்பாகப் பயன்படுத்த உரையின் பக்கங்களில் உள்ள வெற்று இடத்தைக் குறைக்கிறது.",
      "option.miniMargins.title": "மினி ஓரங்கள் (கிட்டத்தட்ட விளிம்பு வரை)",
      "option.miniMargins.description": "இன்னும் குறைக்கிறது, இதனால் உரை கிட்டத்தட்ட திரை விளிம்புகளை ஒட்டி இருக்கும். இதை இயக்கினால் மேலே உள்ள விருப்பம் முடக்கப்படும்.",
